  'settings.chunks': 'Tengingar á hvert niðurhal (0 = sjálfvirkt)',
  'settings.chunksHint': 'Hversu margar tengingar eitt niðurhal opnar þegar ekkert nákvæmara gildir. Regla, eða eitt tiltekið niðurhal, getur nefnt sína eigin tölu og gengur framar þessu. Hýsill sem þolir færri fær samt færri: takmörk hýsils geta aðeins lækkað töluna, aldrei hækkað hana. Með 0 ræður forritið. Fleiri en handfylli tenginga skila engu hjá hýsli sem takmarkar á hverja skrá og eru örugg leið til að fá reikning merktan.',
  'task.chunks': 'Tengingar (0 = almenna stillingin)',
  'task.chunksHint': 'Hversu margar tengingar einmitt þetta niðurhal opnar. Það gengur framar almennu stillingunni og hverri reglu sem setti hana, en aldrei framar hýslinum: hýsill sem þolir færri fær samt færri. Með 0 fellur undantekningin niður og talan ræðst annars staðar á ný.',
  'columns.connection': 'Tenging',

  'props.title': 'Eiginleikar',
  'props.mixed': 'Mörg gildi',
  'props.mixedHint': 'Þessar raðir eru ekki sammála, þess vegna er reiturinn tómur. Ósnertur breytir hann engu; skrifaðu í hann og hver valin röð fær það sem þú skrifaðir.',
  'props.name': 'Heiti',
  'props.nameHint': 'Eitt skráarheiti, aldrei slóð: allt sem skrifar út möppur er skorið niður í eitt heiti. Loknu niðurhali er líka gefið nýtt heiti á disknum, svo listinn og mappan geti ekki stangast á. Það sem er í gangi heldur skránni sem bakendinn hefur opna og tekur nýja heitið þegar það klárast. Það sem ekki er byrjað tekur það strax. Heiti tilheyrir einni skrá, svo þessi reitur býðst aðeins fyrir eina röð.',
  'props.comment': 'Athugasemd',
  'props.commentHint': 'Þín eigin athugasemd um þennan hlekk. Hún er vistuð og sýnd í listanum; ekkert í forritinu fer eftir henni.',
  'props.priority': 'Forgangur',
  'props.priorityHint': 'Hærri fer fyrst. Það endurraðar því sem enn bíður; niðurhal sem þegar er í gangi er ekki sent aftur í biðröðina.',
  'props.autoExtract': 'Afþjappa safnskrár',
  'props.autoExtractHint': 'Hvort skjalasafn er afþjappað þegar niðurhali lýkur. „Erfa“ skilur ákvörðunina eftir hjá stillingasíðu skjalasafna, sem er ekki það sama og af. Rofinn er lesinn þegar afþjöppun fer fram, svo ef þú kveikir á honum núna er líka afþjappað eitthvað sem kláraðist fyrr.',
  'props.inherit': 'Erfa',
