  'settings.access.relay.title': 'Endurvarpi verkefnisins',
  'settings.access.relay.body': 'Relay er milliliður sem gerir öll tilvikin þín aðgengileg utan heimanetsins, þ.e. hvaðan sem er. Þetta býður verkefnið ókeypis.',
  'settings.access.relay.use': 'Nota endurvarpa verkefnisins',
  'settings.access.relay.leadProject': 'Virkar án uppsetningar. Allt sem tilvikin þín segja hvert öðru er dulkóðað, og aðeins þú átt lykilinn.',
  'settings.access.relay.address': 'Vistfang',
  'settings.access.relay.seesButton': 'Hvað sér hann?',
  'settings.access.relay.seesTip': 'Ekki sýnilegt endurvarpanum: tenglarnir þínir, niðurhalið þitt, skrárnar þínar og aðgangslykillinn þinn.\n\nSýnilegt endurvarpanum: IP-tölur tilvika þinna og hvenær þau senda eitthvað.\n\nÞað verður ekki dulkóðað í burtu. Ef það truflar þig, keyrðu þinn eigin endurvarpa.',
