  'settings.access.ownRelay.save': 'Vista',
  'settings.access.ownRelay.everyInstance': 'Þetta vistfang gildir aðeins fyrir þetta tilvik. Sláðu það inn á hverju tilviki.',
  'settings.access.ownRelay.containerLabel': 'Sem eigin gámur',
  'settings.access.ownRelay.containerHint': 'Ef ekkert tilvikanna þinna næst að utan verður relay að standa annars staðar: á þínum netþjóni eða litlum VPS. Settu upp gáminn úr Unraid Community Applications eða með skipuninni hér að neðan.\n\nGámurinn þarf enga uppsetningu: ræstu hann, skrifaðu vistfangið að ofan, búið. Hann geymir ekkert, svo það er ekkert að taka afrit af.',
