  'settings.access.identity.namePlaceholder': 't.d. Heimaþjónn',
  'settings.access.identity.nameHint': 'Boðið fyrst við pörun og í QR-kóðanum hér að neðan, í stað þess sem stýrikerfið eða gámaumhverfið kallar þessa vél. Valfrjálst - skildu eftir autt til að halda áfram að nota það.',
  'settings.access.identity.domainsLabel': 'Þekkt lén',
  'settings.access.identity.domainsHint': 'Er munað sjálfkrafa í fyrsta sinn sem beiðni berst raunverulega í gegnum það, svo það er áfram skráð hér jafnvel þótt síðari beiðnir berist í staðinn um staðarnets-IP-tölu. Bættu einu við handvirkt fyrir lén sem þegar er uppsett en hefur ekki verið heimsótt í gegnum enn - ein full vistfang á línu, t.d. https://kl.example.com.',
  'settings.access.cardTitle': 'Tengja tilvik og fjaraðgangur',
  'settings.access.phrase.body': 'Ein setning tengir öll KnightLoader-tilvikin þín. Búðu hana til hér og límdu í hin tilvikin - enginn reikningur, engin innskráning, ekkert að stilla.',
  'settings.access.phrase.noPasswordWarning': 'Þetta tilvik hefur ekkert lykilorð. Setningin nær til hvers tilviks sem þú tengir með henni, svo hver sem les hana hér nær til þeirra allra, ekki bara þessa. Betra að setja lykilorð hér að ofan fyrst.',
  'settings.access.phrase.activate': 'Búa til setningu',
  'settings.access.phrase.howLead': 'Tólf orð, ekki meira. Svona ferðu að, og þetta gerist:',
  'settings.access.phrase.howStep1': 'Ýttu á „{button}“ á þessu tilviki. Tólf orð birtast.',
  'settings.access.phrase.howStep2': 'Opnaðu KnightLoader í hinni vélinni, farðu á þessa sömu síðu, ýttu á „{button}“ og sláðu inn orðin tólf.',
  'settings.access.phrase.howStep3': 'Búið! Hvort tilvik birtist nú hjá hinu undir „Tilvik“ og þú getur stýrt hvoru sem er frá hvoru sem er. Með kveikt á endurvarpanum eru tilvikin þín aðgengileg utan netsins þíns.',
  'settings.access.phrase.howWhat': 'Orðin eru leyndarmál, ekki heimilisfang. Hvert tilvik reiknar úr þeim tvo lykla: einn til að finna hin, annan til að dulkóða.\n\nTil að finna hvert annað hringir hvert tilvik sjálft í sama mótsstaðinn á netinu. Sá sem sýnir sama lykil er tengdur. Þess vegna þarf ekkert tilvikanna þinna að vera aðgengilegt að utan.\n\nMótsstaðurinn getur ekki lesið. Hann sér orðin þín aldrei og allt sem fer þar í gegn er dulkóðað með seinni lyklinum.',
  'settings.access.phrase.statusDisconnected': 'Ekki tengt',
  'settings.access.phrase.statusHintProject': 'Tengt við relay verkefnisins. Fjaraðgangur er uppsettur.',
  'settings.access.phrase.statusHintOwn': 'Tengt við þitt eigið relay. Fjaraðgangur er uppsettur.',
  'settings.access.phrase.statusHintOff': 'Ekkert relay er virkt. Aðeins er hægt að ná í tilvikin þín á staðarnetinu.',
  'settings.access.phrase.statusHintLost': 'Ekkert samband við relay. KnightLoader heldur áfram að reyna. Þangað til ná tilvikin aðeins hvert til annars á staðarnetinu.',
