  'settings.browsertools.bookmarkletStep2': 'Á hvaða síðu sem er, smelltu á hann (veldu texta fyrst ef þú vilt aðeins hann). Lítill KnightLoader flipi opnast með tengli þeirrar síðu, eða valda textanum, þegar útfylltum - farðu yfir það og bættu því við þaðan sem niðurhal.',
