  'settings.resolvers.moduleUnavailableHint': 'Allt hér fyrir neðan er samt vistað og tekur gildi um leið og yt-dlp verður tiltækt - ekkert tapast við að breyta þessu núna þegar.',
  'settings.resolvers.intro': 'Stillingar fyrir yt-dlp bakendann, sem sækir þær miðla- og streymissíður sem yt-dlp styður sjálft. Hvaða þjónusta sér yfirleitt um tiltekinn hlekk - yt-dlp, debrid reikningur, höfuðlaus JD hliðarvagn - er ákveðið út frá beiningarröð á síðunni Reikningar; hér er einungis lýst því sem yt-dlp gerir eftir að hlekk hefur þegar verið beint til þess.',
