  'settings.torrents.portMapConfirmed': 'Staðfest: gátt {port} er framsend og staðfest að hún sé aðgengileg.',
  'settings.torrents.portMapUnconfirmed': 'Beinirinn samþykkti beiðnina, en ekki tókst að staðfesta að tilfærslan virki í raun. Sumir beinar gera þetta án þess að láta vita - prófaðu tengitengingarpróf utan frá netinu.',
  'settings.torrents.portMapFailed': 'Ekki tókst að framsenda gáttina: {error}',
  'settings.torrents.portMapUnavailable': 'Þessi útgáfa býður ekki enn upp á gáttatilfærslu.',
  'settings.torrents.networkTitle': 'Leit að jafningjum',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Finnur jafningja án nokkurs rekjara, með því að nota aðra BitTorrent-biðlara sem dreifða skrá.',
  'settings.torrents.pex': 'Jafningjaskipti (PEX)',
  'settings.torrents.pexHint': 'Skiptir þekktum jafningjum við þá sem þegar eru tengdir, svo að sveimur með fáa jafningja finnist hraðar.',
  'settings.torrents.privateNote': 'Einka torrent slekkur sjálfkrafa á báðu um leið og lýsigögn þess eru þekkt, sama hvað er stillt hér - samstundis fyrir .torrent-skrá sem hlaðið er upp, eða um leið og eigin lýsigögn segulslóðar berast frá sveimnum. Flestir einkarekjarar banna reikninga sem nota annað hvort.',
  'settings.torrents.engineNote': 'Markhlutfall sáningar, marklengd sáningar og gátt hafa nú áhrif á hverja torrent-skrá sem þessi vél ræsir - gáttin þó aðeins fyrir þá allra fyrstu frá síðustu enduræsingu þessa tilviks, því að eigin torrent-biðlari vélarinnar er byggður aðeins einu sinni og aldrei endurbyggður eftir það; síðari vistun er engu að síður vistuð rétt og tekur gildi frá og með næstu enduræsingu. Sendingarmörk eru enn aðeins vistuð og staðfest, án þess að vélin hafi enn neina leið til að beita þeim á niðurhal sem stendur yfir. DHT og PEX hér fyrir neðan eru í sömu stöðu fyrir venjulega (ekki einka) torrent-skrá: sjálfgefið gildi þessa tilviks nær heldur ekki enn til niðurhals sem stendur yfir, svo að torrent-skrá heldur áfram að sá með báðu virku sama hvað er stillt hér - einka torrent er allt annað mál, sjá athugasemdina hér fyrir neðan. Tilfærsluhnappurinn hér fyrir neðan gerir samt eitthvað raunverulegt: hann biður beininn heiðarlega um að framsenda gáttarnúmerið sem slegið var inn hér að ofan, hvort sem einhver torrent-skrá hlustar á hana núna eða ekki.',
