  'onboarding.step': 'Skref {n} af {total}',
  'onboarding.skip': 'Sleppa',
  'onboarding.back': 'Til baka',
  'onboarding.next': 'Áfram',
  'onboarding.finish': 'Byrja að nota KnightLoader',
  'onboarding.welcome.title': 'Velkomin í KnightLoader',
  'onboarding.welcome.body': 'KnightLoader er sjálfhýst niðurhalsstjórnun: límdu eða slepptu tengli og hann er sóttur af þeim bakenda sem raunverulega sér um hann - innbyggða vélin fyrir einfalda skráartengla, yt-dlp fyrir efnissíður, debrid-þjónusta fyrir hýsingaraðila sem þú borgar nú þegar fyrir, eða höfuðlaust JDownloader fyrir allt annað. Þessi stutta kynning fjallar um einu stillinguna sem borgar sig að athuga áður en þú byrjar.',
  'onboarding.welcome.langLabel': 'Tungumál viðmóts',
  'onboarding.folder.title': 'Hvert eiga skrár að fara?',
  'onboarding.folder.body': 'Þetta er mappan sem lokið niðurhal er skrifað í. Skrifaðu slóð eða flakkaðu um miðlarann til að finna eina - þú getur breytt þessu aftur hvenær sem er á síðu almennra stillinga.',
  'onboarding.accounts.title': 'Úrvalshýsingaraðilar, hvenær sem þú vilt',
  'onboarding.accounts.body': 'Biðröðin virkar alveg án nokkurs reiknings. Þegar þú vilt fullan hraða hjá hýsingaraðila eða debrid-þjónustu sem þú borgar nú þegar fyrir, bættu innskráningu hennar við undir Reikningum - ekkert þarf að stilla hér núna.',
  'onboarding.accounts.link': 'Opna Reikninga',
  'onboarding.finished.title': 'Þú ert tilbúin(n)',
  'onboarding.finished.body': 'Þar með lýkur kynningunni. Hjálparsíðan undir Stillingum er með fulla yfirferð yfir allt annað sem þessi útgáfa gerir, og flestir stýringar bera sína eigin skýringu á bak við (i)-tákn.',

