  'settings.nav.shortcuts': 'Flýtileiðir',
  'settings.shortcuts.subtitle': 'Allar skipanir sem koma með sjálfgefinni flýtileið, flokkaðar eftir því hvar þær eiga við. Breyttu úthlutun, eða endurstilltu hana á sjálfgefið.',
  'settings.shortcuts.empty': 'Engin skipun hefur enn sjálfgefna flýtileið.',
  'settings.shortcuts.change': 'Breyta',
  'settings.shortcuts.reset': 'Endurstilla',
  'settings.shortcuts.resetAll': 'Endurstilla allt á sjálfgefið',
  'settings.shortcuts.resetAllConfirmTitle': 'Endurstilla allar flýtileiðir?',
  'settings.shortcuts.resetAllConfirmBody': 'Sérhver endurúthlutuð flýtileið fer aftur í sjálfgefið gildi sitt. Ekki er hægt að afturkalla þetta.',
  'settings.shortcuts.resetAllConfirm': 'Endurstilla allt',
  'settings.shortcuts.captureTitle': 'Ýttu á nýja flýtileið fyrir „{name}“',
  'settings.shortcuts.captureHint': 'Ýttu á takkasamsetningu, eða Escape til að hætta við.',
