  'settings.downloads.diskTitle': 'Diskpláss',
  'settings.downloads.diskHint': 'Þrjár tölur sem halda niðurhali aftur áður en diskurinn fyllist, ekki eftir á. Allar þrjár eiga við laus bæti á þeim diski sem verið er að skrifa á: liggi vinnumappan á öðrum diski er sá mældur. Núll slekkur á viðkomandi tölu. Það sem þetta getur ekki: ekki er hægt að spyrja hvert kerfi hversu mikið er laust, og þar sem ekkert svar fæst er engu haldið aftur, því vörður sem lokar á allt þegar hann veit ekki myndi stöðva fullkomlega heilbrigða vél.',
