  'settings.feeds.seededHint': 'Fyrsta athugunin á nýrri áskrift skráir allt sem straumurinn ber á þeirri stundu og bætir engu af því við, svo að þér falli ekki allt safn útgefandans í fangið í einu. Aðeins það sem birtist eftir það bætist við.',
  'settings.feeds.remembered': '{n} færslur í minni',
  'settings.feeds.rememberedHint': 'Hversu margar færslur þessi áskrift þekkir aftur, svo að þeim sé ekki bætt við í annað sinn á meðan straumurinn birtir þær enn. Mest 500 á hverja áskrift. Þær elstu detta fyrst út, og færsla sem stendur enn í straumnum er aldrei þar á meðal.',
  'settings.feeds.test': 'Prófa',
  'settings.feeds.testBusy': 'Sæki…',
  'settings.feeds.testHint': 'Sækir þessa slóð einu sinni og sýnir þér hvað stendur í henni, svo að þú sjáir titlana sem sían þín er prófuð á. Aðeins er lesið: ekkert fer í safnarann og ekkert er skráð sem séð, þú mátt því ýta á hnappinn fyrir slóð sem þú hefur ekki vistað enn.',
