  'settings.headerProfiles.title': 'Hausasnið',
  'settings.headerProfiles.hint': 'Sumar síður afhenda skrá aðeins vafra sem er skráður inn, eða þeim sem kemur af einni af þeirra eigin síðum. Snið geymir hausana fyrir nákvæmlega eina síðu, dulkóðaða á sama hátt og lyklarnir að reikningunum þínum, og KnightLoader sendir þá með hverju niðurhali frá þeirri síðu.',
  'settings.headerProfiles.empty': 'Engin hausasnið enn.',
  'settings.headerProfiles.emptyHint': 'Það borgar sig að búa til eitt um leið og niðurhal virkar aðeins á meðan þú ert skráður inn í vafranum.',
  'settings.headerProfiles.add': 'Bæta við sniði',
  'settings.headerProfiles.name': 'Heiti sniðs',
  'settings.headerProfiles.nameHint': 'Heitið sem þú vísar á þetta snið með, jafnt í Packagizer-reglu sem hér. Aðeins bókstafir, tölustafir og - _ eða .',
  'settings.headerProfiles.namePlaceholder': 't.d. forum',
