  'settings.headerProfiles.originHint': 'Límdu inn slóð síðunnar sem þú afritaðir hausana af. Önnur gátt og http í stað https teljast önnur síða og þurfa sitt eigið snið. Undirlén fellur ekki undir snið aðallénsins.',
  'settings.headerProfiles.headers': 'Hausar',
