  'settings.rules.action.category': 'Flokkur',
  'settings.rules.action.categoryHint': 'Raðar tenglum sem passa í eina af skúffunum af Flokkar-síðunni, og hún kemur með sína eigin möppu, sitt sæti í biðröðinni, sinn rofa fyrir afþjöppun og sína reglu um árekstra. Sé þessu ekki breytt hefur engin regla afstöðu til þess og tengillinn verður óraðaður. Nefni þessi regla líka niðurhalsmöppu vinnur sú mappa, og skúffan leggur allt annað til. Að nefna skúffu sem hefur verið eytt er hafnað við vistun, því regla sem vísar á skúffu sem er ekki til gerir bókstaflega ekkert við hvern þann tengil sem hún passar við, án þess að segja frá því.',
  'settings.rules.action.categoryNone': 'Engir flokkar enn. Búðu fyrst til einn á Flokkar-síðunni, annars myndi þessi regla raða tenglum í skúffu sem er ekki til.',
