  'detail.onDiskHint': 'Hvað skráin mælist á disknum á þessari sekúndu, sótt hjá þjóninum í stað þess að vera talið hér. Niðurhal í gangi stækkar milli tveggja augnagota, og þetta er ekki stærðin sem hýsillinn gaf upp.',
  'detail.mirrorOf': 'Afrit af',
  'detail.times': 'Tímastimplar',
  'detail.timesHint': 'Hvenær þessi tengill kom, hvenær honum var síðast breytt og hvenær hann kláraðist. Hvenær yfirfærslan hófst stendur hvergi: forritið hefur aldrei skráð það, og ágiskun út frá hinum þremur væri tala sem fólk færi eftir.',
  'detail.nextTry': 'Næsta tilraun',
  'detail.stalledSince': 'Staðnað síðan',
  'detail.retries': 'Endurtilraunir hingað til',
  'detail.retriesHint': 'Hversu oft hefur verið reynt aftur við þetta niðurhal eftir bilun. Teljarinn fer á núll um leið og niðurhalinu lýkur, lokin lína sýnir því núll þótt atrennurnar hafi verið fjórar. Hversu margar tilraunir eru eftir stendur ekki hér: þakið ræðst af ástæðunni og af hýslinum, og þessi síða getur ekki reiknað það út.',
  'detail.stallRestarts': 'Endurræsingar eftir stöðnun',
  'detail.stallRestartsHint': 'Hversu oft stöðnunarvaktin hefur sjálf ræst þetta niðurhal upp á nýtt. Fer á núll um leið og niðurhalinu lýkur, alveg eins og teljarinn hér fyrir ofan.',
  'detail.failure': 'Hvað fór úrskeiðis',
