  'detail.message': 'Hvað bakendinn sagði',
  'detail.messageHint': 'Setningin frá því sem reyndi að sækja þetta, orðrétt og óþýdd. Þetta er bilunin eins og hún stendur núna og ekkert annað: endurræsing hreinsar hana, og þær sem á undan komu eru hvergi geymdar.',
  'detail.heldBack': 'Haldið aftur af',
  'detail.doing': 'Gerir núna',
  'detail.filtered': 'Tenglasían heldur honum eftir',
  'detail.gaveUp': 'Ekki reynt aftur',
  'detail.gaveUpHint': 'Hér er hætt af ásettu ráði, ekki af því að tilraunirnar séu uppurnar: captcha, fullur diskur eða regla sem segir „aldrei“ um þennan hýsil. Að hækka tilraunafjöldann breytir engu um þetta. Merkingin sjálf er ekki skrifuð í gagnagrunninn, hún er því horfin eftir endurræsingu þótt ástæðan fyrir henni sé það ekki.',
  'detail.rules': 'Reglurnar sem mótuðu þetta',
  'detail.rulesHint': 'Reglurnar sem gripu þennan tengil þegar hann var undirbúinn, í þeirri röð sem þær keyrðu. Þær standa sem heiti í verkinu: regla sem hefur verið endurnefnd síðan finnst ekki lengur, og regla sem aldrei hafði heiti stendur með þeirri stöðu sem hún hafði þá. Smellur opnar hana í regluritlinum.',
  'detail.openRule': 'Opna í regluritlinum',
  'detail.noRules': 'Engin regla snerti þennan tengil.',
  'detail.player': 'Spila',
  'detail.play': 'Spila hér',
  'detail.playHint': 'Spilar skrána beint af þessu tilviki, án þess að sækja hana í annað sinn. Ekkert er sótt fyrr en þú ýtir á spila, og skráin verður áfram þar sem hún er.',
  'detail.playPartial': 'Þetta niðurhal er ekki búið. Aðeins sá hluti sem þegar liggur á disknum spilast, ekki er hægt að stökkva fram fyrir hann, og sumar skrár spila alls ekkert fyrr en síðasta bætið er komið.',
  'detail.playUnsupported': 'Þessi vafri getur ekki spilað þessa skrá. Opnaðu hana eða vistaðu í staðinn úr hægrismelltu valmyndinni.',
  'detail.playRemote': 'Aðeins skrár á þessu tilviki spilast hér. Annað tilvik réttir sínar skrár í einu lagi og án þess að hægt sé að stökkva um, og spilari ræður ekki við það.',
  'detail.playNotLocal': 'JDownloader sótti þetta niðurhal, skráin liggur því á disknum hjá því ferli en ekki á þessum hér.',
  'detail.playNoFile': 'Það er ekkert komið á diskinn til að spila.',
