  'notifications.title': 'Tilkynningar',
  'notifications.titleHint': 'Ákveddu fyrir hvern atburð hvort hann birtist sem lítil tilkynning í forritinu, sem tilkynning frá stýrikerfinu þínu, eða alls ekki. Kerfistilkynning nær aðeins til þín á meðan KnightLoader-flipi er opinn, og hljóðláta stillingin hér fyrir neðan gildir að auki.',
  'notifications.channel.app': 'Í forritinu',
  'notifications.channel.system': 'Kerfistilkynning',
  'notifications.channel.silent': 'Sýna ekkert',
  'notifications.event.downloadDone': 'Niðurhali lokið',
  'notifications.event.downloadDoneHint': 'Hvert einasta niðurhal sem kemst alla leið segir frá sér. Tvö hundruð skrár í biðröðinni þýða tvö hundruð svona tilkynningar, hugsaðu þig því tvisvar um áður en þú sendir þær á kerfið.',
  'notifications.event.downloadFailed': 'Niðurhal mistókst',
  'notifications.event.downloadFailedHint': 'Niðurhal sem gafst upp. Hljóðláta stillingin felur það aldrei.',
