  'notifications.event.extractionDoneHint': 'Safnskrá sem er fullafþjöppuð. Þetta hefur hvergi verið tilkynnt hingað til, þess vegna stendur það í byrjun á „Sýna ekkert“.',
  'notifications.event.extractionFailed': 'Afþjöppun mistókst',
  'notifications.event.extractionFailedHint': 'Safnskrá sem stöðvaðist áður en hún kláraðist. Oftast vantar lykilorðið, og skrárnar liggja kyrrar þar til þú tekur á því.',
  'notifications.event.captchaWaiting': 'Captcha bíður',
  'notifications.event.captchaWaitingHint': 'Captcha-glugginn opnast í þessum flipa hvort sem er. Hann stendur í byrjun á „Sýna ekkert“, því sá gluggi er tilkynningin sjálf á meðan þú horfir á hann. Stilltu hann á kerfistilkynningu, þá nær captcha til þín líka í flipa í bakgrunni, áður en hýsillinn hendir setunni.',
  'notifications.event.captchaFailed': 'Captcha mistókst',
