  'notifications.systemUnavailable': 'Kerfistilkynningar eru ekki í boði hér: vafrinn þinn býður þær aðeins yfir HTTPS eða á localhost. Allt á þessu spjaldi birtist samt í forritinu.',
  'notifications.systemBlocked': 'Vafrinn þinn lokar á tilkynningar fyrir þetta vistfang. Línur sem standa á „Kerfistilkynning“ birtast í forritinu í staðinn, þar til þú leyfir þær aftur í vefsvæðastillingum vafrans þíns.',
  'notifications.systemNotGranted': 'Vafrinn veitti ekki leyfið, þess vegna verður þessi atburður áfram í forritinu. Veldu „Kerfistilkynning“ aftur til að spyrja einu sinni enn.',
