  'disk.title': 'Áfangamöppur',
  'disk.hint': 'Laust og notað pláss á hverri möppu sem niðurhal getur lent í, og hversu mikið biðröðin á enn eftir að skrifa í hverja þeirra. Tölurnar koma úr sömu fyrirspurn og diskmörkin eru prófuð gegn og eru í mesta lagi fáeinna sekúndna gamlar. Laust og notað leggjast ekki alltaf saman í stærð disksins: skráarkerfi heldur sneið eftir handa kerfinu, og kvóti á hvern notanda getur skilið þessu tilviki eftir minna en diskurinn á í raun. Tvær möppur á sama diski sýna hvor um sig þennan sama disk, leggðu því línurnar aldrei saman.',
  'disk.free': 'Laust',
  'disk.used': 'Notað',
  'disk.size': 'Stærð disksins',
  'disk.queued': 'Enn eftir að skrifa',
  'disk.queuedHint': 'Hvað niðurhölin sem enn standa út af myndu bæta í þessa möppu: stærðin sem hýsillinn gaf upp, mínus það sem þegar er komið. Niðurhal sem hýsillinn gefur enga stærð upp á telst hér sem núll, talan er því neðri mörk og aldrei loforð, og þess vegna geta staðið núll bæti við hliðina á heilli röð af niðurhölum. Niðurhal sem þú hefur slökkt á er utan við, sama regla og gildir um teljarana undir listanum. Niðurhal sem er þegar í gangi hefur oftast fengið plássið sitt tekið frá um leið og það fór af stað, bætin þess vantar því þegar í lausa plássið hér við hliðina og leggjast ekki ofan á það.',
  'disk.tasks': '{n} niðurhöl',
  'disk.unknown': 'Þetta kerfi gefur ekki upp laust pláss',
  'disk.unknownHint': 'Ekki er hægt að spyrja hvern kjarna hversu mikið er laust á diski, og þessi smíð hefur engan aðgang að slíkri fyrirspurn á því kerfi sem hún keyrir á. Þar sem svarið vantar er engu haldið aftur: niðurhal fer af stað nákvæmlega eins og áður en diskmörkin urðu til. Þessi lína stendur hér svo að þú getir greint það frá diski sem er í alvöru fullur.',
  'disk.missing': 'Ekki til enn',
  'disk.missingHint': 'Þessa möppu býr sá til sem skrifar fyrstu skrána í hana, hún er því ekki til enn. Tölurnar lýsa {path}, næstu möppu fyrir ofan sem er til, og hún liggur á þeim diski sem niðurhalið myndi lenda á.',
  'disk.measured': 'Mælt við {path}',
  'disk.elsewhereHint': 'Ekki tókst að mæla möppuna sjálfa, þess vegna var mælt á næstu möppu fyrir ofan sem hægt var að mæla. Hafi tengipunktur ekki komið upp getur það verið allt annar diskur en sá sem niðurhalið á að fara á. Líttu á slóðina áður en þú lest eitthvað út úr tölunum.',
  'disk.sampled': 'Lesið fyrir {n} sekúndum',
  'disk.tight': 'Biðröðin kemst ekki fyrir',
  'disk.tightHint': 'Þessari möppu er skuldað meira en er laust á disknum. Þessi lína stöðvar ekkert ein og sér: haldið er aftur af einu niðurhali í einu, þegar röðin kemur að því, eftir tölunum á Niðurhal-síðunni í stillingunum, og niðurhal sem enginn veit stærðina á telst hér alls ekki með.',
  'disk.truncated': 'Ekki eru allar möppur taldar hér',
  'disk.truncatedHint': 'Biðröðin stefnir á fleiri möppur utan þeirra sem eru stilltar en borgar sig að mæla í hverri lesningu, þess vegna vantar þær sem minnst er skuldað. Hver mappa sem þú stilltir er alltaf með.',
  'disk.markLow': 'Hér fyrir neðan fer ekkert nýtt af stað',
  'disk.markStop': 'Hér fyrir neðan stöðvast allt',
  'disk.limits': 'Stilla diskmörkin',
  'disk.stripLabel': 'Pláss í áfangamöppunum',
  'disk.role.downloads': 'Niðurhalsmappa',
  'disk.role.category': 'Flokkamappa',
  'disk.role.work': 'Vinnumappa',
  'disk.role.task': 'Sett á niðurhalinu sjálfu',

  'settings.volume.title': 'Gagnamagnsþak',
  'settings.volume.titleHint': 'Hvað þetta tilvik hefur klárað að sækja, talið á móti þaki sem þú setur, á hvert tímabil. Talin er stærðin sem hýsillinn gaf upp fyrir hvert fullklárað niðurhal. Það sem klárast án uppgefinnar stærðar telst núll, og það sem torrent sendir frá sér telst alls ekki með. Þetta er lestur á niðurhalinu þínu, ekki mæling á línunni þinni: bætin sem beinirinn þinn hreyfði í raun sér enginn hér.',
  'settings.volume.cap': 'Þak á hvert tímabil (GB)',
  'settings.volume.capHint': '0 þýðir ekkert þak: teljarinn heldur áfram að telja og engu er nokkurn tíma haldið aftur. Gígabæti eru hér reiknuð í tugakerfi, eins og þjónustuaðili gefur upp gagnamagn: 500 GB eru 500 000 000 000 bæti en ekki 465 GiB. Diskmörkin ofar á þessari síðu eru tvíundar-GiB, önnur eining fyrir aðra spurningu.',
  'settings.volume.resetDay': 'Dagur mánaðar sem teljarinn byrjar upp á nýtt',
  'settings.volume.resetDayHint': 'Dagurinn í mánuðinum sem teljarinn fer aftur á núll, oftast dagurinn sem gagnamagnið þitt endurnýjast. Í mánuði sem er styttri en dagurinn sem þú valdir byrjar hann þess í stað á síðasta degi þess mánaðar og rennur aldrei yfir í þann næsta. Talið er eftir klukku þjónsins, ekki vafrans þíns, því það er þjónninn sem heldur biðröðinni aftur.',
  'settings.volume.action': 'Þegar þakinu er náð',
  'settings.volume.actionHint': 'Yfirfærsla sem er þegar í gangi er aldrei stöðvuð, sama hvað þú velur: að hætta í miðri skrá hendir bætum sem þú ert þegar búin(n) að eyða. „Aðeins láta mig vita“ breytir engu og skilur teljarann eftir sem allt og sumt. „Ræsa engin fleiri niðurhöl“ lætur það sem er í gangi klárast og heldur biðröðinni aftur þar til teljarinn byrjar upp á nýtt, og hver bíðandi lína segir frá því. „Hægja á öllu“ heldur biðröðinni gangandi á hraðanum hér fyrir neðan.',
  'settings.volume.actionReport': 'Aðeins láta mig vita',
  'settings.volume.actionPause': 'Ræsa engin fleiri niðurhöl',
  'settings.volume.actionThrottle': 'Hægja á öllu',
  'settings.volume.throttle': 'Hraði eftir að þakinu er náð (KiB/s)',
