  'volume.title': 'Sótt gagnamagn',
  'volume.titleHint': 'Fullkláruð niðurhöl lögð saman eftir dögum og eftir mánuðum, út úr niðurhalsferlinum. Ferillinn hefur sín eigin mörk og hægt er að tæma hann í höndunum, mánuðir sem hafa dottið aftan af honum eru því einfaldlega ekki hér. Niðurhal sem þú ræstir aftur telst einu sinni, á þeim degi sem það kláraðist síðast. Reiknað er eftir dagatali þjónsins, í {zone}.',
