  'volume.trimmedHint': 'Ferillinn er kominn að sínum eigin mörkum, allt sem er eldra en elsta færslan hans vantar því líka í þessa kúrfu. Hækkaðu mörk ferilsins á þessari síðu ef þú vilt sjá lengra aftur.',
  'volume.meter': 'Gagnamagn',
  'volume.meterHint': 'Hvað hefur klárast að sækja síðan teljarinn byrjaði síðast upp á nýtt, mælt á móti þakinu á Niðurhal-síðunni í stillingunum. Talan hreyfist þegar niðurhal klárast, ekki á meðan það er í gangi: hún stekkur því frekar en að mjakast. Hún er lögð saman úr niðurhalsferlinum, að tæma ferilinn setur því þennan teljara líka á núll.',
