  'settings.owner.identityTitle': 'Sem hver þetta tilvik skrifar',
  'settings.owner.identityHint': 'Hver skrá sem þetta tilvik býr til fær þennan eiganda og þessi réttindi, og allt sem það ræsir fær þau líka: yt-dlp, ffmpeg og JDownloader sem fylgir með. Í gámi er auðkennið fastsett um leið og gámurinn fer í gang, af þeim reikningi sem hann var ræstur undir, og engu á þessari síðu verður um það breytt.',
  'settings.owner.uid': 'Notandi',
