  'settings.owner.envHow': 'Viljirðu keyra undir öðrum reikningi skaltu nefna hann í ræsiskipuninni: --user <uid>:<gid>. Á Unraid fer það í Extra Parameters, og gáminn þarf að búa til upp á nýtt til að það taki gildi.',
  'settings.owner.desktopNote': 'Skjáborðsforritið keyrir undir þínum eigin reikningi. PUID, PGID og UMASK eru gámastillingar og gera ekkert hér.',
  'settings.owner.noOwners': 'Á þessu kerfi hafa skrár enga eigendur, það er því ekkert að bera saman. Það er ekki bilun.',
  'settings.owner.checkTitle': 'Möppuathugun',
  'settings.owner.checkHint': 'Hér er í raun skrifuð ein skrá og ein undirmappa í hverja möppu, síðan lesið hver á hvort tveggja og hver annar má lesa það, og hvort tveggja fjarlægt aftur. Þetta verður að mæla og má ekki reikna út: samnýtt drif getur borið sínar eigin réttindareglur, og mappa með set-group-id sett gefur annan hóp en þann sem þetta ferli hefur. Athugunin keyrir af sjálfu sér eftir að þú vistar breytta möppu, og alltaf þegar þú ýtir á hnappinn.',
  'settings.owner.run': 'Athuga möppurnar núna',
