  'settings.owner.role.watch': 'Vöktuð mappa',
  'settings.owner.v.ok': 'Skrár lenda hér sem {fileOwner} með {fileMode}, nýjar undirmöppur með {subdirMode}, og mappan sjálf tilheyrir {dirOwner}. Ekkert við það sker sig úr.',
  'settings.owner.v.ownerMismatch': 'Skrár lenda hér sem {fileOwner}, en mappan tilheyrir {dirOwner}. Að lesa þær gengur yfirleitt enn. Að endurnefna þær, færa þær og eyða þeim frá öðrum reikningi gengur ekki, og allt sem gerir ráð fyrir að mappa eigi innihald sitt telur þessar skrár aðskotahluti.',
  'settings.owner.v.groupUnreadable': 'Skrár lenda hér með {fileMode}, aðeins {fileOwner} getur því opnað þær. Það sem keyrir undir öðrum reikningi sér heitin og fær ekkert annað.',
  'settings.owner.v.dirUnreadable': 'Nýjar undirmöppur lenda hér með {subdirMode}. Enginn nema {fileOwner} kemst inn í þær, sama hvað skrárnar í þeim leyfa, og hvert niðurhal lendir í einni slíkri.',
  'settings.owner.v.notWritable': 'Þetta tilvik getur alls ekki skrifað hér: {detail}',
