  'settings.owner.fix.recreate': 'Breytt ræsiskipun krefst þess að gámurinn sé búinn til upp á nýtt. Endurræsing dugir ekki: auðkennið er fastsett um leið og hann fer í gang.',
  'settings.owner.fix.past': 'Skrár sem þegar eru sóttar halda þeim eiganda sem þær voru skrifaðar með. Það sem þú breytir gildir um það sem á eftir kemur, fyrir hitt þarftu skipunina hér að ofan.',
  'settings.selftest.title': 'Sjálfspróf',
