  'settings.selftest.accounts.advice.error': 'Þjónustuaðilinn nefnir eitthvað sem hvorki nýr lykill né bið leysa, til dæmis lokun á vistfangið þitt.',
  'settings.selftest.accounts.readOnlyHint': 'Þessi athugun breytir engu um beininguna. Innskráning sem mistekst hér er tilkynnt en ekki lögð til hliðar: sjálfspróf sem keyrir á meðan línan þín liggur niðri má ekki leggja hvern einasta reikning af í næsta stundarfjórðung.',
  'settings.selftest.relay': 'Endurvarpi',
