  'settings.selftest.clock': 'Klukka og tímabelti',
  'settings.selftest.clock.ok': 'Þessi vél segir {time}, belti {zone}.',
  'settings.selftest.clock.skew': 'Þessa vél og vafrann þinn munar {skew}.',
  'settings.selftest.clock.skewAdvice': 'Önnur hvor gengur rangt og þetta forrit getur ekki sagt hvor. Klukka sem skeikar svona miklu lætur TLS-vottorð líta ógild út og verður til þess að debrid-tókum er hafnað. Athugaðu klukku hýsilsins fyrst, gámurinn sækir tíma sinn þangað.',
  'settings.selftest.clock.utc': 'Tímabeltið er UTC, og þú ert með tímaáætlun uppsetta.',
  'settings.selftest.clock.utcAdvice': 'Tímaáætlunin fer eftir staðartíma þessarar vélar, og sé TZ ekki sett er það UTC. Gluggi sem þú settir á 22:00 byrjar þá klukkan 22:00 UTC, sem í Berlín er 23:00 að vetri og á miðnætti að sumri. Ræstu gáminn með TZ, til dæmis TZ=Europe/Berlin, og endurræstu hann.',
  'settings.selftest.clock.noZoneDB': 'TZ nefnir {zone} og tímabeltagagnagrunninn var ekki hægt að lesa, þess vegna fellur hver tími í þessu ferli aftur á UTC.',
  'settings.selftest.torrentPort': 'Torrent-gátt',
  'settings.selftest.torrentPort.noPort': 'Torrent-vélin velur sér gátt sjálf, og þessi smíð getur ekki lesið til baka hverja hún tók.',
  'settings.selftest.torrentPort.noPortAdvice': 'Settu fasta gátt á Torrent-síðunni. Án hennar er ekkert að áframsenda og ekkert að athuga, og jafningjar á bak við annan beini ná til þín aðeins þegar þeir tengjast fyrst.',
  'settings.selftest.torrentPort.notChecked': 'Gátt {port} er stillt. Ekkert utan þessa nets var spurt, hvort hún sé opin utan frá er því ókunnugt.',
  'settings.selftest.torrentPort.notCheckedAdvice': 'Því getur aðeins vél utan þíns eigin nets svarað, og þetta forrit hefur samband við enga sem þú valdir ekki sjálfur. UPnP-hnappurinn á Torrent-síðunni biður beininn þinn um að áframsenda gáttina og segir heiðarlega hvort hann gat staðfest það. Eitt enn sem vert er að vita: gátt sem er vistuð eftir fyrsta torrent þessarar keyrslu tekur ekki gildi fyrr en eftir endurræsingu.',
  'settings.selftest.proxy.title': 'Öfugur milliþjónn (reverse proxy)',
  'settings.selftest.proxy.hint': 'Hvað vafrinn þinn og þetta tilvik segja hvort um sig um nákvæmlega sömu beiðnina. Þessi fjögur atriði fara úrskeiðis á bak við Nginx Proxy Manager og Traefik, og þrjú af fjórum bila án þess að nokkur villa sjáist.',
  'settings.selftest.proxy.desktopSkip': 'Skjáborðsútgáfan afgreiðir sitt eigið viðmót og hefur engan milliþjón fyrir framan sig, hér er því ekkert að bera saman.',
  'settings.selftest.proxy.host': 'Host-haus',
  'settings.selftest.proxy.host.ok': 'Vafrinn þinn og þetta tilvik eru sammála um að hýsillinn sé {host}.',
  'settings.selftest.proxy.host.rewritten': 'Vafrinn þinn bað um {browser}, þessu tilviki var sagt {server}.',
  'settings.selftest.proxy.host.rewrittenAdvice': 'Milliþjónninn þinn skiptir Host-hausnum út. Þetta tilvik ber Origin vafrans þíns saman við Host, þess vegna er hverri skrift hafnað með 403 og lifandi sýnin opnast aldrei, á meðan síðan sjálf hleðst enn og lítur vel út. Í Traefik skaltu láta passHostHeader vera kveikt. Í nginx skaltu nota proxy_set_header Host $host.',
  'settings.selftest.proxy.proto': 'Áframsend samskiptaregla',
  'settings.selftest.proxy.proto.ok': 'Milliþjónninn segir https, og það er einmitt það sem vafrinn þinn er á.',
  'settings.selftest.proxy.proto.direct': 'Þú náðir beint í þetta tilvik, það er því enginn milliþjónn sem þyrfti að tilkynna neitt.',
  'settings.selftest.proxy.proto.missing': 'Vafrinn þinn er á https og milliþjónninn kom því ekki áleiðis.',
  'settings.selftest.proxy.proto.missingAdvice': 'Án X-Forwarded-Proto heldur þetta tilvik að náðst hafi í það um venjulegt http. QR-kóðinn og pörunarslóðirnar á Fjaraðgangs-síðunni bjóða þá upp á http://-tengla, og gámur sem er afhentur JDownloader er sóttur um http. Í nginx skaltu nota proxy_set_header X-Forwarded-Proto $scheme; Traefik og Caddy setja hana sjálf.',
  'settings.selftest.proxy.prefix': 'Slóðarforskeyti',
  'settings.selftest.proxy.prefix.ok': 'Þetta tilvik er afgreitt við rót {host}, og það er eini staðurinn þar sem það virkar.',
  'settings.selftest.proxy.prefix.underPath': 'Þetta tilvik er afgreitt undir {path}.',
  'settings.selftest.proxy.prefix.underPathAdvice': 'Það byggir hverja skrá og hvert kall sem það gerir út frá rótinni, undirmappa getur því ekki gengið: síðan hleðst kannski og biður svo um /api/, sem milliþjónninn þinn afhendir því sem annars liggur þar. Gefðu því sitt eigið heiti, kl.example.com frekar en example.com/kl.',
  'settings.selftest.proxy.ws': 'WebSocket-Upgrade',
  'settings.selftest.proxy.ws.ok': 'Lifandi tengingin komst á.',
  'settings.selftest.proxy.ws.failed': 'Lifandi tengingin komst ekki á.',
  'settings.selftest.proxy.ws.failedAdvice': 'Þetta er algengasta bilunin á bak við milliþjón, og ekkert annað sýnir þér hana: forritið tengist hljóðlega aftur og aftur út í hið óendanlega, listinn hreinlega hættir að hreyfast, og aðeins endurhleðsla síðunnar sýnir eitthvað nýtt. Í nginx þarf viðkomandi location proxy_http_version 1.1, proxy_set_header Upgrade $http_upgrade og proxy_set_header Connection "upgrade". Nginx Proxy Manager er með rofann Websockets Support á hýslinum. Traefik og Caddy þurfa ekkert.',
  'settings.diagnostics.startupTitle': 'Ræsiskýrsla',
  'settings.diagnostics.startupHint': 'Hvað þetta tilvik athugaði einu sinni við ræsingu: forritin sem það kallar á, hverja möppu sem niðurhal getur lent í, og klukkuna sem tímaáætlun er lesin eftir. Þetta er aflestur og ekki hlið, ekkert af þessu heldur niðurhali aftur eða kemur í veg fyrir að þjónninn fari í gang. Við ræsingu er aðeins litið á hlutina, skrifað er fyrst þegar þú ýtir á „Athuga aftur“.',
