  'settings.diagnostics.startupRunning': 'Enn í athugun. Mappa á samnýttu drifi sem er hætt að svara tekur jafnlangan tíma og það drif þarf til að gefast upp.',
  'settings.diagnostics.startupOff': 'Slökkt er á athuguninni fyrir þetta tilvik (KL_STARTUP_CHECK=0). Ekkert var skoðað, og það er ekki sami hlutur og að ekkert sé að.',
