  'settings.diagnostics.startupStatOnly': 'Við ræsingu var aðeins litið á hlutina: í enga möppu var neitt skrifað. Mappa sem er merkt „Í lagi“ er því mappa sem er til staðar, ekki mappa sem þetta tilvik hefur skrifað í.',
