  'settings.diagnostics.fix.denied': 'Mappan er til og þetta tilvik má ekki skrifa í hana. Í gáminum keyrir KnightLoader sem uid 1000, mappan verður því að tilheyra þeim notanda eða hópi sem hann er í.',
  'settings.diagnostics.fix.readonly': 'Skráakerfið undir þessari möppu er tengt með lesaðgangi einum saman. Ekkert sem þetta tilvik gerir breytir því, tengingunni sjálfri þarf að breyta.',
