  'settings.diagnostics.fix.javaMissing': 'Ekkert Java fannst. Gámamyndin ber eitt með sér, skjáborðsuppsetning notar keyrsluumhverfið sem fylgir eða eitt á PATH. Án þess fer einkaútgáfan af JDownloader ekki í gang, dulkóðaðan gámatengil (.dlc, .ccf, .rsdf) er því alls ekki hægt að opna. Settu JAVA_HOME, eða láttu KL_JD benda á JDownloader sem keyrir annars staðar.',
  'settings.diagnostics.fix.javaNotNeeded': 'Þetta tilvik ræsir ekkert eigið Java-ferli: annaðhvort bendir KL_JD á JDownloader sem keyrir annars staðar, eða slökkt er á einkaútgáfunni með KL_PROVISION_JD=0.',
