  'settings.diagnostics.fix.ffmpegMissing': 'ffmpeg fannst ekki. yt-dlp þarf það til að sameina aðskildu mynd- og hljóðrásirnar sem flestar síður afhenda, niðurhal stöðvast því við aðra hvora þeirra eða kemur til baka án hljóðs.',
