  'settings.diagnostics.fix.utcFallback': 'TZ stendur á {subject} og þetta tilvik gat ekki hlaðið það belti, þess vegna féll það aftur á UTC án þess að segja frá því nokkurs staðar. Hver gluggi í tímaáætluninni fer eftir UTC þar til þetta er lagað. Berðu stafsetninguna saman við beltalistann („Europe/Berlin“), og athugaðu hvort gámamyndin hafi yfirleitt tímabeltagagnagrunn.',
  'settings.diagnostics.fix.noZoneDatabase': 'Á þessu kerfi er enginn tímabeltagagnagrunnur, tímar eru því lesnir alveg án sumartímaskipta. Næturgluggi heldur vetrarstundinni sinni allt sumarið, og ekkert segir frá því þegar það gerist.',
  'settings.diagnostics.fix.tzUnset': 'TZ er ekki sett og enginn staðartími fannst, þetta tilvik keyrir því á UTC. Það gengur, og það er vert að vita: gluggi í tímaáætlun sem er skrifaður 23:00 merkir 23:00 UTC, ekki 23:00 þar sem þú ert.',
