  'settings.resolvers.toolsFrom.none': 'Hvergi',
  'settings.resolvers.toolsYtdlpMissingHint': 'Án yt-dlp er enginn miðlabakendi til: tengli á myndbandssíðu er hafnað með villu síðunnar sjálfrar í stað þess að hann sé sóttur. Í gáminum kemur það úr yt-dlp-pakka gámamyndarinnar, á skjáborði setur þú það upp sjálfur og leggur það annaðhvort á PATH eða lætur KL_YTDLP benda á það. Hnappurinn hér fyrir neðan sækir eintak upp á eigin spýtur ef hvorugt kemur til greina.',
  'settings.resolvers.toolsFfmpegMissingHint': 'Án ffmpeg getur yt-dlp ekki sameinað aðskildu mynd- og hljóðrásirnar sem flestar síður afhenda, niðurhal lendir því annaðhvort sem hljóðlaus myndrás eða mistekst alveg. Án ffprobe mælir „Athugun á fullkláruðu skránni“ ofar á þessari síðu ekkert og segir ekkert um það. Í gáminum koma bæði úr ffmpeg-pakkanum sem gámamyndin setur upp, á skjáborði setur þú þau upp sjálfur og leggur þau á PATH.',
  'settings.resolvers.toolsShadowed': 'Eigið eintak KnightLoader er í gangi. Á meðan það er til staðar eru KL_YTDLP og PATH ekki ræst: í staðinn kæmi {path} að, og það gefur upp {version}.',
