  'settings.resolvers.toolsManagedBroken': 'Sótt eintak er skráð undir {path} og það fer ekki í gang. Í staðinn keyrir sá varakostur sem sýndur er hér að ofan. Sæktu það aftur, eða farðu aftur í eintak kerfisins.',
  'settings.resolvers.toolsActions': 'Halda yt-dlp uppfærðu',
